package mage.player.ai;
import mage.Mana;import mage.abilities.*;import mage.cards.Card;import mage.constants.*;import mage.game.permanent.*;import java.util.*;
import static mage.player.ai.FourthSeatRealGameTest.check;import static mage.player.ai.RecoveryChecks.*;
public final class FourthSeatRecoveredGroupTest {
 static FourthSeatRealGameTest.Fixture base(boolean devoted,int swamps)throws Exception{FourthSeatRealGameTest.Fixture f=new FourthSeatRealGameTest.Fixture();f.game.initializeRollbackOrder();Permanent commander=f.board("l.LathrilBladeOfTheElves","Lathril, Blade of the Elves");f.identifyCommander(commander.getId());f.board("h.HeritageDruid","Heritage Druid");f.board(devoted?"d.DevotedDruid":"l.LlanowarElves",devoted?"Devoted Druid":"Llanowar Elves");for(int i=0;i<swamps;i++)f.board("basiclands.Swamp","Swamp");f.enemyBoard(0,"c.CentaurCourser","Centaur Courser");return f;}
 static void sick(Permanent p)throws Exception{java.lang.reflect.Field x=PermanentImpl.class.getDeclaredField("controlledFromStartOfControllerTurn");x.setAccessible(true);x.setBoolean(p,false);}
 static Card spell(FourthSeatRealGameTest.Fixture f)throws Exception{return f.hand("t.TrystansCommand","Trystan's Command");}
 public static void main(String[]args)throws Exception{
  run("Group tap cannot double-count member mana Elf",()->{FourthSeatRealGameTest.Fixture f=base(false,2);Card c=spell(f);check(!fund(f,c.getSpellAbility()),"True max five advertised six");reject(f,c);});
  for(boolean delayed:new boolean[]{false,true})run("Heritage group first then revalidated six-mana cast expiredBudget="+delayed,()->{FourthSeatRealGameTest.Fixture f=base(false,3);Card c=spell(f);if(delayed)f.game.nextPlayableDelayMillis=100;check(f.bot.priority(f.game),"No group mana action");if(delayed)check(f.game.delayedPlayableCalculations==1,"Expired-budget seam did not run real playable calculation");check(f.game.getState().getZone(c.getId())==Zone.HAND&&f.bot.getManaPool().getMana().getGreen()==3,"Group did not produce exactly3G separately");long tapped=f.game.getBattlefield().getAllActivePermanents(f.bot.getId()).stream().filter(p->p.isCreature(f.game)&&p.isTapped()).count();check(tapped==3,"Group tap cost was not three distinct bodies");cast(f,c,2);check(f.bot.getManaPool().getMana().count()==0,"Six-mana payment incorrect");});
  run("Devoted group then real untap stack then outer cast",()->{FourthSeatRealGameTest.Fixture f=base(true,2);Card c=spell(f);check(f.bot.priority(f.game),"No group action");check(f.bot.getManaPool().getMana().getGreen()==3&&f.game.getState().getZone(c.getId())==Zone.HAND,"First action not group-only");check(f.bot.priority(f.game),"No useful self-untap action");check(!f.game.getStack().isEmpty()&&f.game.getState().getZone(c.getId())==Zone.HAND,"Untap was not actual separate stack ability");int pending=f.game.getStack().size();f.bot.priority(f.game);check(f.game.getStack().size()==pending,"Duplicate self-untap while pending");resolve(f);cast(f,c,2);check(f.bot.getManaPool().getMana().count()==0,"Sequential six-mana cast unpaid");});
  for(String unsafe:new String[]{"sick","damage","toughness1","removed-outer"})run("Useful self-untap rejects unsafe or stale state "+unsafe,()->{FourthSeatRealGameTest.Fixture f=base(true,2);Card c=spell(f);Permanent d=f.game.getBattlefield().getAllActivePermanents(f.bot.getId()).stream().filter(p->p.getName().equals("Devoted Druid")).findFirst().get();if(unsafe.equals("sick")){sick(d);}if(unsafe.equals("damage"))d.damage(1,d.getId(),d.getAbilities().get(0),f.game,false,true);if(unsafe.equals("toughness1")){d.addCounters(mage.counters.CounterType.M1M1.createInstance(),d.getAbilities().get(0),f.game);f.game.applyEffects();}if(unsafe.equals("removed-outer")){check(f.bot.priority(f.game),"Group setup failed");c.moveToZone(Zone.EXILED,null,f.game,false);}int stack=f.game.getStack().size();f.bot.priority(f.game);check(f.game.getState().getZone(c.getId())!=Zone.STACK&&f.game.getStack().size()==stack,"Unsafe/stale sequential plan executed");});
  run("Summoning-sick Elves can pay Heritage target tap cost",()->{FourthSeatRealGameTest.Fixture f=base(false,3);for(Permanent p:f.game.getBattlefield().getAllActivePermanents(f.bot.getId()))if(p.isCreature(f.game))sick(p);Card c=spell(f);cast(f,c,3);});
  for(boolean generic:new boolean[]{false,true})run("Devoted counter recomputes Ghalta GG to1GG generic="+generic,()->{FourthSeatRealGameTest.Fixture f=fixture("g.GhaltaPrimalHunger","Ghalta, Primal Hunger");Permanent d=f.board("d.DevotedDruid","Devoted Druid");d.setTapped(true);f.board("g.Gigantosaurus","Gigantosaurus");Card c=f.game.getCard(f.bot.getCommandersIds().iterator().next());f.bot.getManaPool().addMana(Mana.GreenMana(1),f.game,c.getSpellAbility());if(generic)f.bot.getManaPool().addMana(Mana.ColorlessMana(1),f.game,c.getSpellAbility());if(!generic){reject(f,c);check(d.isTapped()&&d.getCounters(f.game).getCount(mage.counters.CounterType.M1M1)==0,"Unaffordable projected cost spent untap counter");}else{check(f.bot.priority(f.game),"Useful untap absent");check(!f.game.getStack().isEmpty()&&f.game.getState().getZone(c.getId())==Zone.COMMAND,"Untap did not return before commander cast");check(f.game.getPermanent(d.getId()).getCounters(f.game).getCount(mage.counters.CounterType.M1M1)==1,"Real untap counter cost missing");resolve(f);cast(f,c,2);check(f.bot.getManaPool().getMana().count()==0,"Recomputed1GG not paid exactly");}});
  run("Group plans exclude outer-reserved Elf",()->{FourthSeatRealGameTest.Fixture f=base(false,3);Permanent elf=f.game.getBattlefield().getAllActivePermanents(f.bot.getId()).stream().filter(p->p.getName().equals("Llanowar Elves")).findFirst().get();java.lang.reflect.Field r=ComputerPlayerFourthSeat.class.getDeclaredField("pendingTapReservations");r.setAccessible(true);r.set(f.bot,new HashSet<UUID>(Collections.singleton(elf.getId())));java.lang.reflect.Method groups=Class.forName("mage.player.ai.FourthSeatManaDependencyPolicy").getDeclaredMethod("listGroupTapPlans",mage.game.Game.class,ComputerPlayerFourthSeat.class);groups.setAccessible(true);List<?> plans=(List<?>)groups.invoke(null,f.game,f.bot);check(plans.isEmpty(),"Group reused outer-reserved tap body");});
  finish("RECOVERED_GROUP");
 }
}
